def transform(grid):
    h, w = len(grid), len(grid[0])

    # The most common color is the fill color inside the lattice.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    fill = max(counts, key=counts.get)

    def dominant(seq):
        freq = {}
        for v in seq:
            freq[v] = freq.get(v, 0) + 1
        color = max(freq, key=freq.get)
        return color, freq[color]

    # Lattice lines are rows/columns dominated by a color other than the fill.
    row_lines = []
    for r in range(h):
        color, n = dominant(grid[r])
        if color != fill and n >= 0.6 * w:
            row_lines.append(r)

    col_lines = []
    for c in range(w):
        color, n = dominant([grid[r][c] for r in range(h)])
        if color != fill and n >= 0.6 * h:
            col_lines.append(c)

    if not row_lines or not col_lines:
        return [[fill]]

    # The line color is the most common dominant color among lattice lines.
    sep_counts = {}
    for r in row_lines:
        color, _ = dominant(grid[r])
        sep_counts[color] = sep_counts.get(color, 0) + 1
    for c in col_lines:
        color, _ = dominant([grid[r][c] for r in range(h)])
        sep_counts[color] = sep_counts.get(color, 0) + 1
    sep = max(sep_counts, key=sep_counts.get)

    # Keep only lattice lines participating in the marked region.
    rows = [r for r in row_lines if any(grid[r][c] != sep for c in col_lines)]
    cols = [c for c in col_lines if any(grid[r][c] != sep for r in row_lines)]

    if len(rows) < 2 or len(cols) < 2:
        return [[fill]]

    out = []
    for r1, r2 in zip(rows, rows[1:]):
        line = []
        for c1, c2 in zip(cols, cols[1:]):
            corners = (grid[r1][c1], grid[r1][c2],
                       grid[r2][c1], grid[r2][c2])
            line.append(corners[0] if all(v == corners[0] for v in corners) else fill)
        out.append(line)
    return out
